import android.content.Context
import com.abhi.ganasuno.data.MediaArchive
import java.io.*
import java.nio.file.Files
fun main(){val root=Files.createTempDirectory("v14-archive").toFile();try{val c=Context(File(root,"a").apply{mkdirs()});val d=Context(File(root,"b").apply{mkdirs()});val name="12345678-1234-1234-1234-123456789abc.audio";File(c.filesDir,"offline-media").mkdirs();File(c.filesDir,"offline-media/$name").writeText("audio");val bytes=ByteArrayOutputStream().also{MediaArchive.write(c,it,"settings payload")}.toByteArray();var validated=false;var applied=false;check(MediaArchive.restore(d,ByteArrayInputStream(bytes),{check(it=="settings payload");validated=true},{check(validated);check(it=="settings payload");applied=true})==1);check(applied);check(File(d.filesDir,"offline-media/$name").readText()=="audio");val bad=Context(File(root,"bad").apply{mkdirs()});check(runCatching{MediaArchive.restore(bad,ByteArrayInputStream(bytes),{error("Invalid settings")},{error("Should not apply")})}.isFailure);check(!File(bad.filesDir,"offline-media/$name").exists());check(bad.filesDir.listFiles().orEmpty().none{it.name.startsWith("restore-")});println("6 settings archive assertions passed (filesystem stubs)")}finally{root.deleteRecursively()}}
